import{_ as h,o as t,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Vì sao gia đình cần hình dung về &quot;con muốn trở thành ai&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"portrait/vi-sao-can.md","filePath":"portrait/vi-sao-can.md"}'),c={name:"portrait/vi-sao-can.md"};function o(g,n,r,u,m,e){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="vi-sao-gia-đinh-can-hinh-dung-ve-quot-con-muon-tro-thanh-ai-quot" tabindex="-1">Vì sao gia đình cần hình dung về &quot;con muốn trở thành ai&quot; <a class="header-anchor" href="#vi-sao-gia-đinh-can-hinh-dung-ve-quot-con-muon-tro-thanh-ai-quot" aria-label="Permalink to &quot;Vì sao gia đình cần hình dung về &amp;quot;con muốn trở thành ai&amp;quot;&quot;">​</a></h1><p>Trên trang này# Vì sao gia đình cần hình dung về &quot;con muốn trở thành ai&quot; <a href="#vi-sao-gia-đinh-can-hinh-dung-ve-con-muon-tro-thanh-ai">​</a> Không phải để định đoạt tương lai của con. Mà vì <strong>mọi quyết định học tập đều đang ngầm dựa trên một hình dung nào đó</strong> — và nếu không nói ra, hình dung đó vừa không được kiểm tra, vừa thường không phải của con.</p><h2 id="ban-đa-co-mot-hinh-dung-roi-​" tabindex="-1">Bạn đã có một hình dung rồi <a href="#ban-đa-co-mot-hinh-dung-roi">​</a> <a class="header-anchor" href="#ban-đa-co-mot-hinh-dung-roi-​" aria-label="Permalink to &quot;Bạn đã có một hình dung rồi [​](#ban-đa-co-mot-hinh-dung-roi)&quot;">​</a></h2><p>Thử nghĩ về những quyết định đã ra trong năm qua: cho con học thêm môn nào, có cho đi học vẽ không, có ép con thi trường chuyên không, có bắt con bỏ game để học không. Mỗi quyết định đó đều trả lời một câu hỏi ngầm: <em>&quot;cái gì quan trọng cho tương lai của con?&quot;</em> Bạn đã có câu trả lời — chỉ là nó chưa bao giờ được viết ra, nên chưa bao giờ được xem lại. Portrait không tạo ra hình dung mới. Nó lôi cái đang có ra ánh sáng.</p><h2 id="bon-thu-chi-xuat-hien-khi-ban-viet-no-ra-​" tabindex="-1">Bốn thứ chỉ xuất hiện khi bạn viết nó ra <a href="#bon-thu-chi-xuat-hien-khi-ban-viet-no-ra">​</a> <a class="header-anchor" href="#bon-thu-chi-xuat-hien-khi-ban-viet-no-ra-​" aria-label="Permalink to &quot;Bốn thứ chỉ xuất hiện khi bạn viết nó ra [​](#bon-thu-chi-xuat-hien-khi-ban-viet-no-ra)&quot;">​</a></h2><p><strong>Bố và mẹ có thể đang hình dung hai đứa trẻ khác nhau.</strong> Chuyện này phổ biến hơn nhiều người nghĩ, và nó chỉ lộ ra trong lúc cãi nhau về một quyết định cụ thể — chọn trường, cho học thêm, cho nghỉ hè đi đâu. Lúc đó thì đã muộn để bàn bình tĩnh. Viết Portrait ra và thấy hai bản khác nhau là một buổi tối khó chịu, nhưng nó rẻ hơn nhiều so với ba năm kéo co. <strong>Con có hình dung riêng, và thường chưa ai hỏi.</strong> Có những đứa trẻ chưa từng được hỏi câu này một cách nghiêm túc. Câu trả lời đầu tiên thường ngây ngô hoặc chỉ để làm vừa lòng bố mẹ. Câu trả lời thứ ba, thứ tư, sau vài tháng, mới là thật. <strong>Mâu thuẫn giữa các mong muốn hiện ra.</strong> Muốn con đỗ chuyên, muốn con ngủ đủ 8 tiếng, muốn con chơi thể thao, muốn con giỏi tiếng Anh, muốn con có tuổi thơ. Từng cái đều hợp lý. Đặt cạnh nhau trong một tuần 168 giờ thì lộ ra là chúng đang tranh nhau. Portrait không giải quyết mâu thuẫn đó — nhưng nó khiến bạn phải chọn một cách có ý thức, thay vì để mặc cho việc gấp gáp nhất thắng. <strong>Bạn có cách đánh giá lời khuyên từ bên ngoài.</strong> Khi ai đó nói &quot;phải cho con học thêm cái này&quot;, có Portrait thì câu hỏi trở nên trả lời được: <em>cái này phục vụ mảng nào?</em> Không có Portrait thì mọi lời khuyên nghe đều có lý, và gia đình chạy theo hết cái này tới cái khác.</p><h2 id="voi-chinh-đua-tre-​" tabindex="-1">Với chính đứa trẻ <a href="#voi-chinh-đua-tre">​</a> <a class="header-anchor" href="#voi-chinh-đua-tre-​" aria-label="Permalink to &quot;Với chính đứa trẻ [​](#voi-chinh-đua-tre)&quot;">​</a></h2><p>Đây là phần ít được nói tới nhưng có lẽ quan trọng nhất. Một đứa trẻ chỉ được đánh giá bằng điểm số sẽ tin rằng <strong>giá trị của nó là điểm số</strong>. Đây không phải chuyện triết lý xa vời — nó là cơ chế trực tiếp đằng sau việc một học sinh sụp đổ sau một kỳ thi trượt. Một đứa trẻ có Portrait thì có nhiều cách hơn để nhìn về bản thân: người thích chế tạo, người bơi giỏi, người bạn tốt, người dám hỏi khi không hiểu. Điểm kém vẫn đau, nhưng nó không phá huỷ toàn bộ hình ảnh bản thân — vì hình ảnh đó không được xây trên một chân duy nhất. Và khi con được tham gia viết Portrait, việc học đổi tính chất: từ <em>thứ bố mẹ bắt làm</em> sang <em>thứ phục vụ điều chính con muốn</em>. Không phải lúc nào cũng thành công, nhưng đó là con đường duy nhất dẫn tới một đứa trẻ tự chủ.</p><h2 id="khong-can-đung-chi-can-ro-​" tabindex="-1">Không cần đúng, chỉ cần rõ <a href="#khong-can-đung-chi-can-ro">​</a> <a class="header-anchor" href="#khong-can-đung-chi-can-ro-​" aria-label="Permalink to &quot;Không cần đúng, chỉ cần rõ [​](#khong-can-đung-chi-can-ro)&quot;">​</a></h2><p>Portrait viết năm con lớp 6 gần như chắc chắn sẽ sai. Không sao cả — mục đích không phải dự đoán đúng. Mục đích là để cả nhà <strong>đang nói về cùng một thứ</strong>, và biết rõ mình đang không đồng ý ở chỗ nào. Một Portrait sai nhưng rõ ràng vẫn tốt hơn nhiều so với ba hình dung mơ hồ không ai nói ra. Bắt đầu thế nào Đừng bắt đầu bằng nghề nghiệp. Hỏi những câu dễ hơn nhiều:</p><ul><li>Con thích làm gì nhất trong tuần vừa rồi?</li><li>Có việc gì con làm mà quên cả thời gian không?</li><li>Con muốn giỏi cái gì mà bây giờ chưa giỏi?</li><li>Ba năm nữa, con muốn mình khác bây giờ ở chỗ nào? Bốn câu này ra được nhiều thứ hơn hẳn câu &quot;lớn lên con muốn làm nghề gì&quot;. Bạn không cần biết con sẽ trở thành ai. Bạn chỉ cần cả nhà cùng nói về nó — trước khi việc học chiếm hết chỗ của cuộc trò chuyện đó. <a href="/portrait/milestone">Milestone gắn vào Portrait thế nào →</a></li></ul>',11)])])}const v=h(c,[["render",o]]);export{s as __pageData,v as default};
